def compute(vars):
    adjustment = vars["v1"]
    as_reported = vars["v2"]
    if as_reported == 0:
        return None

    percentage = adjustment / as_reported * 100
    return {
        "value": percentage,
        "trace": {
            "adjustment": adjustment,
            "as_reported": as_reported,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
